# Let me check different definitions of Fibonacci
def fib1(n):
    """fib(0)=0, fib(1)=1"""
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a + b
    return a

def fib2(n):
    """fib(1)=0, fib(2)=1 (shifted)"""
    if n <= 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1
    a, b = 0, 1
    for _ in range(3, n+1):
        a, b = b, a + b
    return a

print("fib1 (standard):")
for i in range(15):
    print(f"fib1({i}) = {fib1(i)}")

print("\nfib2 (shifted):")
for i in range(15):
    print(f"fib2({i}) = {fib2(i)}")

print(f"\nfib1(14) = {fib1(14)}")
print(f"fib1(15) = {fib1(15)}")
print(f"fib2(14) = {fib2(14)}")
